tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';

const manifest = JSON.parse(readFileSync('work/lib/package.json', 'utf8'));
const { readMinor, mulDivMinor } = await import(new URL(manifest.exports, new URL('./work/lib/', import.meta.url)));
const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const dto = value => ({ unit: 'EUR-cent', value: value.toString() });

const settlement = rows.map(({ id, unitMinor, quantity, kind }) => {
  assert(Number.isSafeInteger(quantity));
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, 'floor');
  if (kind === 'standard') {
    return { id, net: dto(net), fee: dto(mulDivMinor(net, 1n, 10n, 'floor')) };
  }

  assert.equal(kind, 'manual');
  return {
    id,
    net: dto(net),
    fee: null,
    status: 'blocked',
    requiredDecision: 'Марине нужно утвердить ставку сбора и режим округления для manual.',
  };
});

const expectedAmounts = [
  ['CR', '-3', '-1'],
  ['CS', '38', '3'],
  ['CT', '22', null],
];

function verify(output) {
  assert.deepEqual(output.map(({ id, net, fee }) => [id, net.value, fee?.value ?? null]), expectedAmounts);
  for (const { net, fee } of output) {
    for (const amount of fee === null ? [net] : [net, fee]) {
      assert.deepEqual(Object.keys(amount).sort(), ['unit', 'value']);
      assert.equal(amount.unit, 'EUR-cent');
      assert.equal(readMinor(amount.value).toString(), amount.value);
    }
  }
  assert.equal(output[2].fee, null);
  assert.equal(output[2].status, 'blocked');
  assert.match(output[2].requiredDecision, /Марине.*ставку.*округления/);
}

verify(settlement);
writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
verify(JSON.parse(readFileSync('settlement.json', 'utf8')));
NODE
cat settlement.json"

